<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/runtime.php';
require_once __DIR__ . '/../includes/actions.php';
require_once __DIR__ . '/../includes/laser_calculator.php';
$laserApi = isset($_GET['api']);
function cp_laser_api_response(array $data, int $status = 200): void {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store, private, max-age=0');
    header('X-Content-Type-Options: nosniff');
    echo json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}
if ($laserApi && !current_user()) cp_laser_api_response(['ok'=>false, 'message'=>'Tu sesión expiró. Vuelve a iniciar sesión en SISACT.'], 401);
require_auth();
$laserUser = current_user();
$laserUserId = (int)($laserUser['id'] ?? 0);
if ($laserUserId <= 0) {
    if ($laserApi) cp_laser_api_response(['ok'=>false, 'message'=>'Usuario no válido. Vuelve a iniciar sesión.'], 403);
    http_response_code(403);
    exit('No se pudo identificar al usuario de SISACT. Vuelve a iniciar sesión.');
}
header('Cache-Control: no-store, private, max-age=0');
header('X-Content-Type-Options: nosniff');
$laserError = '';
try {
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
        $csrf = $_POST['_csrf'] ?? null;
        if (!is_string($csrf) || !csrf_check($csrf)) {
            if ($laserApi) cp_laser_api_response(['ok'=>false, 'message'=>'La sesión del formulario expiró. Recarga la página.'], 403);
            throw new InvalidArgumentException('La sesión del formulario expiró. Recarga la página.');
        }
        $rawPayload = $_POST['payload'] ?? '';
        if (!is_string($rawPayload) || strlen($rawPayload) > 120000) throw new InvalidArgumentException('El contenido enviado no es válido.');
        $payload = json_decode($rawPayload, true);
        if (!is_array($payload)) throw new InvalidArgumentException('Revisa los datos enviados por el cotizador.');
        $action = $_POST['action'] ?? '';
        if ($action === 'save_configuration' && $laserApi) {
            $state = $payload['state'] ?? null;
            $version = $payload['version'] ?? '';
            if (!is_array($state) || !is_string($version)) throw new InvalidArgumentException('Revisa el catálogo enviado.');
            $saved = cp_laser_save_shared($state, $version, $laserUserId);
            log_activity('update', 'calculators', 'Catálogo y tarifas de láser actualizados');
            cp_laser_api_response(array_merge(['ok'=>true], $saved));
        }
        if ($action === 'use_result' && !$laserApi) {
            if (!is_array($payload['job'] ?? null) || !is_array($payload['machine'] ?? null)) throw new InvalidArgumentException('Completa el cálculo antes de usar el resultado.');
            $_SESSION['cp_pending_quote'] = cp_laser_prepare_quote($payload['job'], $payload['machine']);
            log_activity('calculate', 'calculators', 'Corte y grabado láser preparado para cotización');
            header('Location: /admin/cotizacion_nueva.php?from=laser', true, 303);
            exit;
        }
        throw new InvalidArgumentException('Acción no válida para el cotizador.');
    }
    if ($laserApi) cp_laser_api_response(array_merge(['ok'=>true], cp_laser_shared_state()));
} catch (CpLaserVersionConflict $error) {
    if ($laserApi) cp_laser_api_response(['ok'=>false, 'message'=>$error->getMessage()], 409);
    $laserError = $error->getMessage();
} catch (InvalidArgumentException $error) {
    if ($laserApi) cp_laser_api_response(['ok'=>false, 'message'=>$error->getMessage()], 422);
    $laserError = $error->getMessage();
} catch (Throwable $error) {
    error_log('[SISACT Laser V2] ' . $error->getMessage());
    if ($laserApi) cp_laser_api_response(['ok'=>false, 'message'=>'No se pudo guardar el catálogo en SISACT. Revisa la conexión e inténtalo de nuevo.'], 500);
    $laserError = 'No se pudo preparar la cotización. Revisa el cálculo e inténtalo de nuevo.';
}
$laserBootstrapError = '';
try { $laserBootstrap = cp_laser_shared_state(); }
catch (Throwable $error) {
    error_log('[SISACT Laser V2] ' . $error->getMessage());
    $laserBootstrap = ['state'=>cp_laser_initial_state(), 'version'=>'', 'exists'=>false];
    $laserBootstrapError = 'No se pudo cargar el catálogo compartido. Revisa la conexión con SISACT antes de guardar cambios.';
}
$laserBootstrap['csrf'] = csrf_token();
$laserBootstrap['error'] = $laserBootstrapError;
$title = 'Cotizador láser';
require __DIR__ . '/../includes/header.php';
$laserBusinessName = trim((string)($company['trade_name'] ?? '')) ?: 'Colibrí Print México';
$laserStorageKey = 'sisact-laser-v1:' . substr(hash('sha256', __DIR__), 0, 12) . ':' . $laserUserId;
?>
